mapper.select:
select

from billing_apply_recipient b
where 1 = 1

    and b.recipients_name = #{recipientsName,jdbcType=VARCHAR}


    and b.recipients_phone = #{recipientsPhone,jdbcType=VARCHAR}


    and b.address = #{address,jdbcType=VARCHAR}


    and b.create_by_id = #{curUserId}

order by b.id desc
limit 1
